function convertToAssets(uint256 shares) public view returns (uint256) {
    uint256 rho = pot.rho();
    uint256 chi = (block.timestamp > rho) ? _rpow(pot.dsr(), block.timestamp - rho) * pot.chi() / RAY : pot.chi();
    return shares * chi / RAY;
}

function previewRedeem(uint256 shares) external view returns (uint256) { return convertToAssets(shares); }
function maxWithdraw(address owner) external view returns (uint256) { return convertToAssets(balanceOf[owner]); }
function maxRedeem(address owner) external view returns (uint256) { return balanceOf[owner]; }
function totalAssets() external view returns (uint256) { return convertToAssets(totalSupply); }
function previewWithdraw(uint256 assets) external view returns (uint256) {
    uint256 rho = pot.rho();
    uint256 chi = (block.timestamp > rho) ? _rpow(pot.dsr(), block.timestamp - rho) * pot.chi() / RAY : pot.chi();
    return _divup(assets * RAY, chi);
}
function _divup(uint256 x, uint256 y) internal pure returns (uint256 z) { unchecked { z = x != 0 ? ((x - 1) / y) + 1 : 0; } }

contract Pot (// SPDX-License-Identifier: AGPL-3.0-or-later, pragma solidity ^0.6.12): uint256 public dsr; uint256 public chi; uint256 public rho; uint256 public Pie; mapping (address => uint256) public pie; uint256 constant ONE = 10 ** 27;
function _rmul(uint x, uint y) internal pure returns (uint z) { z = _mul(x, y) / ONE; }
function drip() external returns (uint tmp) {
    require(now >= rho, "Pot/invalid-now");
    tmp = _rmul(_rpow(dsr, now - rho, ONE), chi);
    uint chi_ = _sub(tmp, chi);
    chi = tmp;
    rho = now;
    vat.suck(address(vow), address(this), _mul(Pie, chi_));
}

function _convertToAssets(uint256 shares, Math.Rounding rounding) internal view virtual returns (uint256) {
    return shares.mulDiv(totalAssets() + 1, totalSupply() + 10 ** _decimalsOffset(), rounding);
}

function totalAssets() public view virtual override returns (uint256) {
    return (vToken.balanceOf(address(this)) * vToken.exchangeRateStored()) / EXP_SCALE;
}
function _decimalsOffset() internal view virtual override returns (uint8) {
    return 18 - ERC20Upgradeable(asset()).decimals();
}

abstract contract ERC4626StataTokenUpgradeable is ERC4626Upgradeable, IERC4626StataToken (// SPDX-License-Identifier: BUSL-1.1, pragma solidity ^0.8.17)
function _convertToAssets(uint256 shares, Math.Rounding rounding) internal view virtual override returns (uint256) {
    // * @notice share * exchangeRate / RAY
    return shares.mulDiv(_rate(), RAY, rounding);
}
function _convertToShares(uint256 assets, Math.Rounding rounding) internal view virtual override returns (uint256) {
    // * @notice assets * RAY / exchangeRate
    return assets.mulDiv(RAY, _rate(), rounding);
}
function _rate() internal view returns (uint256) { return POOL.getReserveNormalizedIncome(asset()); }
function totalAssets() public view override returns (uint256) { return _convertToAssets(totalSupply(), Math.Rounding.Floor); }
function maxWithdraw(address owner) public view override returns (uint256) { return convertToAssets(maxRedeem(owner)); }

function getNormalizedIncome(DataTypes.ReserveData storage reserve) internal view returns (uint256) {
    uint40 timestamp = reserve.lastUpdateTimestamp;
    if (timestamp == block.timestamp) {
      return reserve.liquidityIndex;
    } else {
      return MathUtils.calculateLinearInterest(reserve.currentLiquidityRate, timestamp).rayMul(reserve.liquidityIndex);
    }
}
